"""Processor-owned runtime for MCP integrations."""

from __future__ import annotations

import asyncio
from datetime import timedelta
from typing import TYPE_CHECKING, Any, Mapping, Optional

import structlog

from rasa.agents.schemas.agent_tool_schema import AgentToolSchema
from rasa.mantle.config.agent_spec import resolve_tool_timeout
from rasa.mantle.tools.mcp_connection_pool import MCPConnectionPool
from rasa.mantle.tools.mcp_import_spec import MCPToolReference
from rasa.mantle.tools.result import ToolResult
from rasa.shared.utils.mcp.server_connection import MCPServerConnection
from rasa.tracing.langfuse_telemetry import langfuse_span

if TYPE_CHECKING:
    from rasa.mantle.model_archive.bootstrap import ModelBootstrap

structlogger = structlog.get_logger()


class MCPRuntime:
    """Live MCP connections for one processor.

    Bootstrap holds import refs and server YAML. This object holds connections
    and the imported ``(skill, tool) → server / schema`` maps used at dispatch.

    For a skill ``banking`` importing ``mcp/core_banking:get_balance``::

        tool_to_server = {"banking": {"get_balance": "core_banking"}}
        mcp_tool_schemas = {
            "banking": {
                "get_balance": AgentToolSchema(
                    name="get_balance",
                    description="Return the balance for an account.",
                    parameters={
                        "type": "object",
                        "properties": {"account_id": {"type": "string"}},
                        "required": ["account_id"],
                    },
                    strict=False,
                )
            }
        }
    """

    def __init__(self, default_tool_timeout: Optional[float] = None) -> None:
        # Shared connection pool for all MCP servers.
        self.shared_connection_pool = MCPConnectionPool()

        # ``{skill_id: {tool_name: server_id}}`` — dispatch routing.
        self.tool_to_server: dict[str, dict[str, str]] = {}

        # ``{skill_id: {tool_name: tool_schema}}`` — allowlisted
        self.mcp_tool_schemas: dict[str, dict[str, AgentToolSchema]] = {}
        self._default_tool_timeout = resolve_tool_timeout(default_tool_timeout)

        # Drain state: ``close`` stops accepting calls, then waits for the ones
        # already running. ``_drained`` is set whenever ``_in_flight`` is zero.
        self._in_flight = 0
        self._closed = False
        self._drained = asyncio.Event()
        self._drained.set()

    def has_mcp_tool(self, skill_id: str, tool_name: str) -> bool:
        """Return whether *tool_name* is an imported MCP tool for *skill_id*."""
        return tool_name in self.tool_to_server.get(skill_id, {})

    def server_id_for(self, skill_id: str, tool_name: str) -> str:
        """Return the MCP server that provides *tool_name* for *skill_id*."""
        server_id = self.tool_to_server.get(skill_id, {}).get(tool_name)
        if server_id is None:
            raise RuntimeError(
                f"MCP tool {tool_name!r} is not imported by skill {skill_id!r}."
            )
        return server_id

    async def session_for(self, server_id: str) -> Any:
        """Return an active MCP session for *server_id*."""
        return await self.shared_connection_pool.get_connection(
            server_id
        ).ensure_active_session()

    async def prepare(self, static_data: "ModelBootstrap") -> None:
        """Connect imported servers, list tools, and bind allowlisted names."""
        mcp_tool_allowlist = static_data.mcp_tool_allowlist
        server_ids = {
            reference.server_id
            for references in mcp_tool_allowlist.values()
            for reference in references
        }
        if not server_ids:
            return

        settings = static_data.mcp_servers
        remote_tool_schemas_by_server: dict[str, dict[str, AgentToolSchema]] = {}
        prepared = False
        try:
            for server_id in sorted(server_ids):
                if settings is None or server_id not in settings.servers:
                    raise ValueError(
                        f"MCP server {server_id!r} is imported by a skill but is "
                        "missing from integrations.yml."
                    )
                config = settings.servers[server_id]
                connection = MCPServerConnection.from_config(
                    settings.to_connection_config(server_id)
                )
                with langfuse_span(
                    name="mcp.connect",
                    metadata={"server_id": server_id},
                ):
                    await connection.connect()
                self.shared_connection_pool.add(server_id, connection, config)

                session = await connection.ensure_active_session()
                with langfuse_span(
                    name="mcp.list_tools",
                    metadata={"server_id": server_id},
                ) as span:
                    listed_tools = await session.list_tools()
                    span.update(output={"tool_count": len(listed_tools.tools)})
                remote_tool_schemas_by_server[server_id] = {
                    tool.name: AgentToolSchema.from_mcp_tool(tool)
                    for tool in listed_tools.tools
                }

            self.tool_to_server, self.mcp_tool_schemas = _filter_imported_tools(
                mcp_tool_allowlist, remote_tool_schemas_by_server
            )
            prepared = True
        finally:
            # Close on Exception *and* BaseException (CancelledError) without
            # catching the latter. A cancelled prepare must not leave pooled
            # sessions open after a successful connect().
            if not prepared:
                await self.close()

    async def call_mcp_tool(
        self,
        server_id: str,
        tool_name: str,
        arguments: Mapping[str, Any],
    ) -> ToolResult:
        """Call an imported MCP tool through the agent's shared connection pool."""
        if self._closed:
            raise RuntimeError("MCP runtime is closed.")
        self._in_flight += 1
        self._drained.clear()
        try:
            return await self._invoke_mcp_tool(server_id, tool_name, arguments)
        finally:
            self._in_flight -= 1
            if self._in_flight == 0:
                self._drained.set()

    async def _invoke_mcp_tool(
        self,
        server_id: str,
        tool_name: str,
        arguments: Mapping[str, Any],
    ) -> ToolResult:
        from rasa.shared.utils.mcp.utils import build_mcp_meta, call_tool_with_meta

        config = self.shared_connection_pool.get_config(server_id)
        timeout_seconds = float(config.tool_timeout or self._default_tool_timeout)
        meta = build_mcp_meta(config.meta_map, {})

        async with self.shared_connection_pool.lock_for(server_id):
            with langfuse_span(
                name="mcp.call_mcp_tool",
                metadata={
                    "server_id": server_id,
                    "argument_count": len(arguments),
                },
                span_input={
                    "tool_name": tool_name,
                    "tool_args": sorted(arguments.keys()),
                },
            ) as span:
                result = await call_tool_with_meta(
                    await self.session_for(server_id),
                    tool_name,
                    dict(arguments),
                    timedelta(seconds=timeout_seconds),
                    meta,
                )
                span.update(output={"is_error": bool(result.isError)})

        if result.isError:
            structlogger.warning(
                "mantle.mcp.tool_call_failed",
                server_id=server_id,
                tool_name=tool_name,
                is_error=True,
            )
            raise RuntimeError(
                f"MCP tool {tool_name!r} on server {server_id!r} failed."
            )
        if result.structuredContent is not None:
            payload: Any = result.structuredContent
        else:
            payload = [content.model_dump() for content in result.content]
        return ToolResult(llm_response=payload)

    async def close(self) -> None:
        """Close all pooled connections after in-flight calls finish.

        Safe to call more than once. New calls are rejected once close starts.
        """
        self._closed = True
        await self._drained.wait()
        await self.shared_connection_pool.close()
        self.tool_to_server = {}
        self.mcp_tool_schemas = {}


def _filter_imported_tools(
    mcp_tool_allowlist: Mapping[str, tuple[MCPToolReference, ...]],
    remote_tool_schemas_by_server: Mapping[str, Mapping[str, AgentToolSchema]],
) -> tuple[dict[str, dict[str, str]], dict[str, dict[str, AgentToolSchema]]]:
    """Keep only imported tools; fail if a declared import is missing remotely."""
    tool_to_server: dict[str, dict[str, str]] = {}
    mcp_tool_schemas: dict[str, dict[str, AgentToolSchema]] = {}
    for skill_id, references in mcp_tool_allowlist.items():
        for reference in references:
            server_tools = remote_tool_schemas_by_server.get(reference.server_id)
            if server_tools is None:
                raise ValueError(
                    f"Skill {skill_id!r} references unconfigured MCP server "
                    f"{reference.server_id!r}."
                )
            tool_schema = server_tools.get(reference.tool_name)
            if tool_schema is None:
                raise ValueError(
                    f"MCP server {reference.server_id!r} does not expose imported "
                    f"tool {reference.tool_name!r} for skill {skill_id!r}."
                )
            tool_to_server.setdefault(skill_id, {})[reference.tool_name] = (
                reference.server_id
            )
            mcp_tool_schemas.setdefault(skill_id, {})[reference.tool_name] = tool_schema
    return tool_to_server, mcp_tool_schemas
